"""
Phylax Polkit Authentication Agent Theme Updater
"""

from config import PHYLAX_DIR


def update_phylax(pal):
    PHYLAX_DIR.mkdir(parents=True, exist_ok=True)
    style_css = PHYLAX_DIR / "style.css"

    content = f"""/*
 * Material You Theme for Phylax (GTK4 Polkit Authentication Agent)
 * Auto-generated by change-wallpaper using materialyoucolor
 */

/* Window */
window.auth-window.background,
window.auth-window {{
    background-color: {pal["surface"]};
    border-radius: 16px;
    border: 1px solid {pal["outline_variant"]};
}}

.auth-container {{
    padding: 18px 24px;
    background-color: {pal["surface"]};
}}

/* Typography */
.auth-header {{
    color: {pal["primary"]};
    font-size: 16px;
    font-weight: bold;
    margin-bottom: 8px;
}}

.auth-message {{
    color: {pal["on_surface"]};
    font-size: 13px;
    margin-bottom: 12px;
}}

.auth-retry {{
    color: {pal["error"]};
    font-size: 12px;
    margin-top: 4px;
}}

/* Identity dropdown */
dropdown.auth-identity > button.toggle {{
    background: none;
    background-color: {pal["surface_container"]};
    border: 1px solid {pal["outline_variant"]};
    border-radius: 10px;
    color: {pal["on_surface"]};
    padding: 6px 12px;
}}

dropdown.auth-identity > button.toggle:hover {{
    background-color: {pal["surface_container_high"]};
}}

dropdown.auth-identity > popover.menu > contents,
dropdown.auth-identity listview {{
    background-color: {pal["surface_container"]};
    border: 1px solid {pal["outline_variant"]};
    border-radius: 10px;
}}

dropdown.auth-identity listview > row {{
    padding: 6px 12px;
    color: {pal["on_surface"]};
}}

dropdown.auth-identity listview > row:hover,
dropdown.auth-identity listview > row:selected {{
    background-color: {pal["primary_container"]};
    color: {pal["on_primary_container"]};
}}

dropdown.auth-identity listview > row:focus:not(:hover) {{
    background-color: transparent;
}}

/* Password entry */
.auth-password,
entry.auth-password {{
    background-color: {pal["surface_container_lowest"]};
    border: 1px solid {pal["outline_variant"]};
    border-radius: 10px;
    color: {pal["on_surface"]};
    padding: 8px 12px;
}}

entry.auth-password:focus-within {{
    border-color: {pal["primary"]};
    outline-color: {pal["primary"]};
}}

/* Buttons */
.auth-buttons {{
    margin-top: 14px;
}}

.auth-cancel {{
    background-color: {pal["surface_container"]};
    border: 1px solid {pal["outline_variant"]};
    border-radius: 10px;
    color: {pal["on_surface_variant"]};
    padding: 6px 16px;
    font-weight: 500;
}}

.auth-cancel:hover {{
    background-color: {pal["surface_container_high"]};
    color: {pal["on_surface"]};
}}

.auth-confirm {{
    background-color: {pal["primary"]};
    border: 1px solid {pal["primary"]};
    border-radius: 10px;
    color: {pal["on_primary"]};
    padding: 6px 16px;
    font-weight: 600;
}}

.auth-confirm:hover {{
    background-color: {pal["primary_container"]};
    color: {pal["on_primary_container"]};
}}
"""
    style_css.write_text(content)
